using BARANG.Core.Domain.Workflow;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;
internal static class WorkflowConfig { internal static void Base<T>(EntityTypeBuilder<T> b,string table) where T:class { b.ToTable(table);b.HasKey("Id");b.Property<Guid>("Id").HasColumnName("id");b.Property<Guid>("CompanyId").HasColumnName("company_id");b.HasAlternateKey("CompanyId","Id"); } }
internal sealed class WorkflowInstanceConfiguration:IEntityTypeConfiguration<WorkflowInstance>{public void Configure(EntityTypeBuilder<WorkflowInstance>b){WorkflowConfig.Base(b,"workflow_instances");b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.DefinitionCode).HasColumnName("definition_code").HasMaxLength(80);b.Property(x=>x.ProviderInstanceId).HasColumnName("provider_instance_id").HasMaxLength(150);b.Property(x=>x.CurrentStage).HasColumnName("current_stage").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.StartedAtUtc).HasColumnName("started_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.SuspendedAtUtc).HasColumnName("suspended_at_utc");b.Property(x=>x.CompletedAtUtc).HasColumnName("completed_at_utc");b.Property(x=>x.LastReason).HasColumnName("last_reason").HasMaxLength(500);b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.OrderId}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.Status,x.CurrentStage});b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class HumanTaskConfiguration:IEntityTypeConfiguration<HumanTask>{public void Configure(EntityTypeBuilder<HumanTask>b){WorkflowConfig.Base(b,"human_tasks");b.Property(x=>x.WorkflowInstanceId).HasColumnName("workflow_instance_id");b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.Stage).HasColumnName("stage").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.TaskTypeCode).HasColumnName("task_type_code").HasMaxLength(60);b.Property(x=>x.RequiredPermissionCode).HasColumnName("required_permission_code").HasMaxLength(150);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.Priority).HasColumnName("priority");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.DueAtUtc).HasColumnName("due_at_utc");b.Property(x=>x.ClaimedByUserId).HasColumnName("claimed_by_user_id");b.Property(x=>x.ClaimedAtUtc).HasColumnName("claimed_at_utc");b.Property(x=>x.CompletedAtUtc).HasColumnName("completed_at_utc");b.Property(x=>x.Outcome).HasColumnName("outcome").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.OutcomeReason).HasColumnName("outcome_reason").HasMaxLength(500);b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.Status,x.DueAtUtc});b.HasIndex(x=>new{x.CompanyId,x.ClaimedByUserId,x.Status});b.HasIndex(x=>new{x.CompanyId,x.WorkflowInstanceId,x.Stage});b.HasOne<WorkflowInstance>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.WorkflowInstanceId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class WorkflowSlaConfiguration:IEntityTypeConfiguration<WorkflowSlaPolicy>{public void Configure(EntityTypeBuilder<WorkflowSlaPolicy>b){WorkflowConfig.Base(b,"workflow_sla_policies");b.Property(x=>x.Stage).HasColumnName("stage").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.DurationMinutes).HasColumnName("duration_minutes");b.Property(x=>x.EscalationPermissionCode).HasColumnName("escalation_permission_code").HasMaxLength(150);b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.Stage}).IsUnique();}}
internal sealed class WorkflowEscalationConfiguration:IEntityTypeConfiguration<WorkflowEscalation>{public void Configure(EntityTypeBuilder<WorkflowEscalation>b){WorkflowConfig.Base(b,"workflow_escalations");b.Property(x=>x.HumanTaskId).HasColumnName("human_task_id");b.Property(x=>x.Level).HasColumnName("level");b.Property(x=>x.EscalatedAtUtc).HasColumnName("escalated_at_utc");b.Property(x=>x.TargetPermissionCode).HasColumnName("target_permission_code").HasMaxLength(150);b.HasIndex(x=>new{x.CompanyId,x.HumanTaskId,x.Level}).IsUnique();b.HasOne<HumanTask>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.HumanTaskId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class WorkflowHistoryConfiguration:IEntityTypeConfiguration<WorkflowHistory>{public void Configure(EntityTypeBuilder<WorkflowHistory>b){WorkflowConfig.Base(b,"workflow_history");b.Property(x=>x.WorkflowInstanceId).HasColumnName("workflow_instance_id");b.Property(x=>x.HumanTaskId).HasColumnName("human_task_id");b.Property(x=>x.EventType).HasColumnName("event_type").HasMaxLength(60);b.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at_utc");b.Property(x=>x.ActorUserId).HasColumnName("actor_user_id");b.Property(x=>x.Summary).HasColumnName("summary").HasMaxLength(500);b.HasIndex(x=>new{x.CompanyId,x.WorkflowInstanceId,x.OccurredAtUtc,x.Id});b.HasOne<WorkflowInstance>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.WorkflowInstanceId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class WorkflowReconciliationConfiguration:IEntityTypeConfiguration<WorkflowReconciliationIssue>{public void Configure(EntityTypeBuilder<WorkflowReconciliationIssue>b){WorkflowConfig.Base(b,"workflow_reconciliation_issues");b.Property(x=>x.WorkflowInstanceId).HasColumnName("workflow_instance_id");b.Property(x=>x.IssueCode).HasColumnName("issue_code").HasMaxLength(80);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.DetectedAtUtc).HasColumnName("detected_at_utc");b.Property(x=>x.ResolvedAtUtc).HasColumnName("resolved_at_utc");b.HasIndex(x=>new{x.CompanyId,x.WorkflowInstanceId,x.IssueCode,x.Status});b.HasOne<WorkflowInstance>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.WorkflowInstanceId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
